namespace lob {

/// Trading Intent generated by the Quantitative Alpha Strategy
struct alignas(64) StrategyOrderIntent {
    enum class Action : uint8_t {
        Hold = 0,
        QuoteBid,
        QuoteAsk,
        QuoteTwoSided,
        AggressiveTakeBuy,
        AggressiveTakeSell,
        CancelAll
    };

    Action   action{Action::Hold};
    uint8_t  side{0};       // 0 = Buy, 1 = Sell
    uint32_t bid_price{0};
    uint32_t ask_price{0};
    uint32_t qty{0};
    uint64_t timestamp_ns{0};

    // Market context snapshot forwarded along pipeline
    uint32_t best_bid{0};
    uint32_t best_ask{0};
    uint32_t best_bid_vol{0};
    uint32_t best_ask_vol{0};
    double   mid_price{0.0};
    double   micro_price{0.0};
    float    obi{0.0f};
};

/// Production Configuration for Pipelined Trading Engine
struct EngineConfig {
    int core_ingress{0};
    int core_matching{1};
    int core_strategy{2};
    int core_execution{3};
    RiskConfig risk_config{};
    std::string symbol{"AAPL"};
    uint32_t quote_lot_size{100};
    float obi_threshold{0.25f};
    float aggressive_obi_threshold{0.60f};
    uint32_t min_spread_ticks{2};
    std::array<float, 4> obi_level_weights{1.0f, 0.5f, 0.25f, 0.125f};
    double inventory_gamma{0.005};
    bool enable_core_pinning{true};
    bool enable_udp_streaming{true};
    std::string udp_host{"127.0.0.1"};
    uint16_t udp_port{9876};
    bool paper_execution{true};
    uint32_t synthetic_price_cents{15'000};
    uint32_t synthetic_order_qty{100};
};

/// High-Performance Pipelined 4-Core Autonomous Trading Engine
/// Thread 1: Market Data Ingress (MoldUDP64/ITCH) -> Core Pinned
/// Thread 2: Limit Order Book FIFO Matcher       -> Core Pinned
/// Thread 3: SIMD Alpha Strategy & Pricing      -> Core Pinned
/// Thread 4: Pre-Trade Risk, OMS & OUCH Wire    -> Core Pinned
class PipelinedTradingEngine {
public:
    using EngineConfig = lob::EngineConfig;

    PipelinedTradingEngine();
    explicit PipelinedTradingEngine(const EngineConfig& config);
    ~PipelinedTradingEngine();


    /// Start the 4-core pipelined engine
    void start();

    /// Signal graceful shutdown and join threads
    void stop();

    /// Feed a raw network packet into the ingress pipeline
    bool inject_network_packet(const uint8_t* buffer, size_t length, uint64_t timestamp_ns = 0);

    /// Replay adapter for PcapReader
    size_t process_datagram(const uint8_t* buffer, size_t length, uint64_t timestamp_ns = 0) {
        return inject_network_packet(buffer, length, timestamp_ns) ? 1 : 0;
    }

    [[nodiscard]] bool is_running() const noexcept { return running_.load(std::memory_order_relaxed); }
    [[nodiscard]] const ShmTelemetryBlock* get_telemetry() const noexcept { return telemetry_mgr_.get(); }
    [[nodiscard]] ShmTelemetryBlock* get_telemetry() noexcept { return telemetry_mgr_.get(); }

    void print_status_dashboard() const;

private:
    void matching_thread_loop();
    void strategy_thread_loop();
    void execution_thread_loop();

    EngineConfig config_;
    alignas(64) std::atomic<bool> running_{false};
    alignas(64) std::atomic<bool> matching_done_{true};
    alignas(64) std::atomic<bool> strategy_done_{true};
    uint64_t expected_mold_sequence_{0};
    bool mold_sequence_initialized_{false};
    char mold_session_[10]{};

    // Thread-safe lock-free SPSC communication channels
    static constexpr size_t RING_CAPACITY = 65536;
    struct IngressMessage { uint8_t length{0}; uint8_t bytes[64]{}; };
    RingBuffer<IngressMessage, RING_CAPACITY> ingress_to_match_ring_{};
    RingBuffer<Top5BookView, RING_CAPACITY> match_to_alpha_ring_{};
    RingBuffer<StrategyOrderIntent, RING_CAPACITY> alpha_to_exec_ring_{};

    // Core Components
    std::unique_ptr<OrderBook> book_;
    std::unique_ptr<FeedHandler> feed_handler_;
    RiskEngine risk_engine_;
    OrderStateMachine<65536> oms_;
    TcaEngine<16384, 32768> tca_engine_;
    ShmTelemetryManager telemetry_mgr_;
    LatencyProfiler<100'000> exec_profiler_;
    UdpMarketDataPublisher udp_pub_;
    uint64_t last_active_bid_token_{0};
    uint64_t last_active_ask_token_{0};

    // Pipelined Worker Threads
    std::thread matching_thread_;
    std::thread strategy_thread_;
    std::thread execution_thread_;

    // Engine Statistics Counters
    alignas(64) std::atomic<uint64_t> messages_ingested_{0};
    alignas(64) std::atomic<uint64_t> orders_matched_{0};
    alignas(64) std::atomic<uint64_t> trades_executed_{0};
    alignas(64) std::atomic<uint64_t> volume_traded_{0};
    alignas(64) std::atomic<uint64_t> risk_rejections_{0};
    alignas(64) std::atomic<uint64_t> token_generator_{1};
};

} // namespace lob

